import { tags } from "typia";

/**
 * Aggregated refund and dispute metrics segment for the admin governance
 * overview.
 *
 * Derived from shopping_mall_refund_and_dispute_stats and related analytical
 * sources, providing high-level insight into refund and dispute activity over
 * the current reporting period and, optionally, recent trends.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallRefundAndDisputeStatsSummary = {
  /**
   * Total number of refund operations executed in the primary reporting
   * window.
   */
  totalRefundCount: number & tags.Type<"int32">;

  /**
   * Total amount refunded during the primary reporting window, in the
   * platform's base currency.
   */
  totalRefundAmount: number;

  /** Total number of disputes opened in the primary reporting window. */
  totalDisputeCount: number & tags.Type<"int32">;

  /**
   * Refund rate expressed as a ratio or percentage of refunds relative to
   * total orders in the reporting window, as defined by business rules. For
   * example, 0.05 may represent a 5% refund rate.
   */
  refundRate: number;

  /**
   * Dispute rate expressed as a ratio or percentage of disputes relative to
   * total orders in the reporting window.
   */
  disputeRate: number;

  /**
   * ISO 4217 currency code representing the currency used for monetary refund
   * values.
   */
  currency: string;
};
